/** Today's deal for a product, shown as a popup. */
class DealDialogFragment : DialogFragment() {
    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog =
        AlertDialog.Builder(requireContext())
            .setTitle("Deal unlocked")
            .setMessage(requireArguments().getString(ARG_MESSAGE))
            .setPositiveButton("Nice", null)
            .create()

    companion object {
        private const val ARG_MESSAGE = "message"
        fun newInstance(message: String) = DealDialogFragment().apply { arguments = bundleOf(ARG_MESSAGE to message) }
    }
}

/** Loads a product's detail and announces today's deal in a popup. */
@OptIn(DelicateCoroutinesApi::class)
object DealLoader {
    fun load(activity: FragmentActivity, productId: Int, onLoaded: (Product) -> Unit) {
        GlobalScope.launch(Dispatchers.Main) {
            val product = ProductRepository.byId(productId)
            onLoaded(product)
            if (product.dealPercent > 0) {
                DealDialogFragment
                    .newInstance("${product.dealPercent}% off ${product.name}, today only.")
                    .show(activity.supportFragmentManager, "deal")
            }
        }
    }
}

@Composable
fun DetailScreen(productId: Int, onBuyNow: (Int) -> Unit, modifier: Modifier = Modifier) {
    val activity = LocalContext.current as FragmentActivity
    var product by remember { mutableStateOf<Product?>(null) }
    LaunchedEffect(productId) {
        DealLoader.load(activity, productId) { product = it }
    }

    val loaded = product
    if (loaded == null) {
        Box(modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            CircularProgressIndicator(Modifier.testTag("detail_loading"))
        }
        return
    }

    Column(
        modifier = modifier.fillMaxSize().padding(24.dp).testTag("detail_screen"),
        verticalArrangement = Arrangement.spacedBy(12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(loaded.emoji, fontSize = 96.sp)
        Text(loaded.name, style = MaterialTheme.typography.headlineSmall, modifier = Modifier.testTag("detail_name"))
        Text(loaded.priceLabel(), style = MaterialTheme.typography.titleLarge, modifier = Modifier.testTag("detail_price"))
        Text(loaded.description, style = MaterialTheme.typography.bodyMedium)
        Button(
            onClick = { onBuyNow(loaded.id) },
            modifier = Modifier.fillMaxWidth().testTag("buy_now"),
        ) { Text("Buy now") }
    }
}

package com.shubhasai.monkeymart.data

import kotlinx.coroutines.delay

data class Product(
    val id: Int,
    val name: String,
    val emoji: String,
    val pricePaise: Long,
    val description: String,
    val dealPercent: Int,
)

fun Product.priceLabel(): String = "₹%,d".format(pricePaise / 100)

/** In-memory catalogue that behaves like a slow backend. */
object ProductRepository {

    private val products = listOf(
        Product(1, "Banana Bunch", "🍌", 6_000, "Six ripe Robusta bananas, monkey approved.", 10),
        Product(2, "Coconut Water", "🥥", 4_500, "Tender coconut water, no added sugar.", 15),
        Product(3, "Mango Box", "🥭", 49_900, "A dozen Alphonso mangoes from Ratnagiri.", 20),
        Product(4, "Peanut Butter", "🥜", 29_900, "Crunchy, 1 kg jar.", 5),
        Product(5, "Jungle Hammock", "🏕️", 189_900, "Cotton hammock for two, holds 200 kg.", 25),
        Product(6, "Vine Swing", "🌿", 99_900, "Hand-braided swing for balconies.", 12),
        Product(7, "Monkey Plush", "🐒", 79_900, "Soft toy, 40 cm, machine washable.", 30),
        Product(8, "Leaf Umbrella", "🍃", 59_900, "Compact umbrella with a leaf print.", 8),
    )

    suspend fun all(): List<Product> {
        delay(800)
        return products
    }

    /** Product detail, including today's deal, from a slow endpoint. */
    suspend fun byId(id: Int): Product {
        delay(5_000)
        return products.first { it.id == id }
    }

    fun cached(id: Int): Product? = products.firstOrNull { it.id == id }
}

