class MainActivityRecreateTest {

    @Test
    fun recreatedActivitiesAreNotRetained() {
        ActivityScenario.launch(MainActivity::class.java).use { scenario ->
            var firstRef: WeakReference<MainActivity>? = null
            scenario.onActivity { firstRef = WeakReference(it) }
            assertNotNull(firstRef?.get())

            repeat(3) { scenario.recreate() }

            repeat(5) {
                Runtime.getRuntime().gc()
                System.runFinalization()
                if (firstRef?.get() == null) return@repeat
                Thread.sleep(100)
            }

            assertNull("Destroyed MainActivity is still reachable", firstRef?.get())
        }
    }
}
